-- #773: an attachment's thumbnail, stored as its own object next to the
-- attachment (generated by #774, served by #775).
--
-- Like `storage_key`, an object key in the bucket, never a public URL.
-- Nullable and without a default: NULL means the attachment has no
-- thumbnail — a PDF or a video, or an attachment stored before thumbnails
-- were generated and not caught up yet. Not UNIQUE: nothing writes it yet,
-- and the key scheme belongs to the generator (#774).
--
-- RLS: `event_attachments_isolation` (0002, rewritten by 0042) filters
-- whole rows through the event's group, so it covers this column as is.
ALTER TABLE event_attachments
    ADD COLUMN thumbnail_key TEXT;

COMMENT ON COLUMN event_attachments.thumbnail_key IS
    'Object key of the attachment''s thumbnail in the bucket (issue #773), never a public URL. NULL when the attachment has none: a PDF, a video, or one stored before thumbnails were generated.';
